import type { ComponentStyleVariantConfig, ComponentProps, Theme } from "@types";
import type { TooltipProps } from "./tooltip.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { boxShadowToDropShadow } from "@theme/utils/css-transforms";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Tooltip";

// Generate child element class names for the component, should match available style slots
export const TooltipClasses = {
  root: "exp-textura_tooltip",
  content: "exp-textura_tooltip_content",
  triggerWrapper: "exp-textura_tooltip_trigger_wrapper",
  arrow: "exp-textura_tooltip_arrow",
  arrowTop: "exp-textura_tooltip_arrow_top",
  arrowBottom: "exp-textura_tooltip_arrow_bottom",
  arrowLeft: "exp-textura_tooltip_arrow_left",
  arrowRight: "exp-textura_tooltip_arrow_right",
  hotkey: "exp-textura_tooltip_hotkey",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  light: {
    root: {
      backgroundColor: theme.tooltip.light.color.background,
      color: theme.tooltip.light.color.content,
    },
    arrow: {
      fill: theme.tooltip.light.color.background,
    },
    arrowPath: {
      stroke: theme.tooltip.light.color.background,
    },
    hotkey: {
      backgroundColor: theme.tooltip.light.hotkey.color.background,
      color: theme.tooltip.light.hotkey.color.content,
    },
  },
});

const generateStyles = (props: TooltipProps & ComponentProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<TooltipProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    pointerEvents: "none",
    borderRadius: theme.toRem(theme.tooltip.border.radius),
    filter: boxShadowToDropShadow(theme.dropShadow.md, theme),
    maxWidth: theme.getSpacing(44),
    backgroundColor: theme.tooltip.dark.color.background,
    color: theme.tooltip.dark.color.content,
    padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
    ...theme.typography.body.mdEmphasis,

    [`&.${TooltipClasses.triggerWrapper}`]: {
      all: "unset",
      display: "block",
      pointerEvents: "auto",
      ...styleSlots?.triggerWrapper,
    },

    [`.${TooltipClasses.content}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.content,
    },

    [`.${TooltipClasses.hotkey}`]: {
      height: theme.toRem(24),
      display: "flex",
      alignItems: "center",
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
      marginInlineEnd: `-${theme.toRem(theme.spacing[4])}`,
      backgroundColor: theme.tooltip.dark.hotkey.color.background,
      color: theme.tooltip.dark.hotkey.color.content,
      ...theme.typography.body.smEmphasis,
      lineHeight: theme.typography.lineHeight[12],
      whiteSpace: "nowrap",
      ...styleSlots?.hotkey,
    },

    [`.${TooltipClasses.arrow}`]: {
      strokeWidth: 1,
      fill: theme.tooltip.dark.color.background,
      // Fixes a visual artifact where a small line can be seen between the arrow and the tooltip
      transform: "translateY(-1px)",
      "& > path": {
        stroke: theme.tooltip.dark.color.background,
        strokeDashoffset: -147,
        strokeDasharray: 67,
        strokeWidth: theme.toRem("0.5px"),
        ...styleSlots?.arrowPath,
      },
      ...styleSlots?.arrow,
    },

    [`.${TooltipClasses.arrowTop}`]: {
      top: "calc(100% - 1px) !important",
      ...styleSlots?.arrowTop,
    },

    [`.${TooltipClasses.arrowBottom}`]: {
      bottom: "calc(100% - 1px) !important",
      ...styleSlots?.arrowBottom,
    },

    [`.${TooltipClasses.arrowLeft}`]: {
      insetInlineStart: "calc(100% - 1px) !important",
      ...styleSlots?.arrowLeft,
    },

    [`.${TooltipClasses.arrowRight}`]: {
      insetInlineEnd: "calc(100% - 1px) !important",
      ...styleSlots?.arrowRight,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledTooltip = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<TooltipProps>((props) => generateStyles(props));
